        for(size_t 순번=0;순번<개수;순번++)넣기(мярка_данни,용량한도,&в_срок_позиция,низ_данни[순번]);while(왼쪽&&너비>(int)개수){넣기(мярка_данни,용량한도,&в_срок_позиция,' ');너비--;}
